package com.example.inventoryservice.dto.request;
import jakarta.validation.constraints.*;
import java.math.BigDecimal;
public class InventoryRequest { @NotNull private Long partnerId; @NotBlank private String itemType; @NotBlank private String name; @NotNull private BigDecimal price; private Integer availability; private String status; private String details; public Long getPartnerId(){return partnerId;} public void setPartnerId(Long v){this.partnerId=v;} public String getItemType(){return itemType;} public void setItemType(String v){this.itemType=v;} public String getName(){return name;} public void setName(String v){this.name=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){this.price=v;} public Integer getAvailability(){return availability;} public void setAvailability(Integer v){this.availability=v;} public String getStatus(){return status;} public void setStatus(String v){this.status=v;} public String getDetails(){return details;} public void setDetails(String v){this.details=v;} }